import type { Messages } from "./types";

// The AI-Empowered Youth Studio tools (ages 10 to 17): Teach the Machine,
// Feed Simulator, Fake or Real?, System Mapper and Vibe Code Studio, plus the pieces they share
// ("studio.youth."). Keys are "studio.<tool-id>.something". Each row is
// [key, English, French, Swahili], so the three languages stay side by side.
// Like the other Studio tool texts, everything except name and desc is
// loaded only where a tool is shown (lib/i18n/client-messages.ts).

type Row = readonly [string, string, string, string];

function build(sections: Array<readonly [string, readonly Row[]]>): Messages {
  const out: Messages = { en: {}, fr: {}, sw: {} };
  for (const [prefix, rows] of sections) {
    for (const [k, en, fr, sw] of rows) {
      const key = `${prefix}.${k}`;
      out.en[key] = en;
      out.fr[key] = fr;
      out.sw[key] = sw;
    }
  }
  return out;
}

